class Main {void main(String[] args)throws Exception {var in=new java.util.Scanner(System.in,java.nio.charset.StandardCharsets.UTF_8);String result="Некорректный месяц";if(in.hasNext()){try{int n=Integer.parseInt(in.next());String[] months={"январь","февраль","март","апрель","май","июнь","июль","август","сентябрь","октябрь","ноябрь","декабрь"};if(n>=1&&n<=12)result=months[n-1];}catch(NumberFormatException invalid){}}System.out.print(result);System.exit(7);}}
